ildren: [\n            Positioned.fill(\n              child: ClipRRect(\n                borderRadius: BorderRadius.circular(\n                  windowData.isMaximized ? 0 : 12,\n                ),\n                child: Column(\n                  children: [\n                    GestureDetector(\n                      onPanUpdate: windowData.isMaximized\n                          ? null\n                          : (details) {\n                              onPositionChanged(\n                                windowData.position + details.delta,\n                              );\n                            },\n                      onDoubleTap: onMaximize,\n                      child: Container(\n                        height: 38,\n                        width: double.infinity,\n                        decoration: BoxDecoration(\n                          color: isDark\n                              ? Colors.black.withValues(alpha: 0.9)\n                              : Colors.white.withValues(alpha: 0.95),\n                          border: Border(\n                            bottom: BorderSide(\n                              color: onSurfaceColor.withValues(alpha: 0.05),\n                            ),\n                          ),\n                        ),\n                        child: Padding(\n                          padding: const EdgeInsets.symmetric(horizontal: 12.0),\n                          child: Row(\n                            children: [\n                              _WindowControl(\n                                color: Colors.redAccent,\n                                onTap: onClose,\n                                icon: Icons.close,\n                              ),\n                              const SizedBox(width: 8),\n                              _WindowControl(\n                                color: Colors.orangeAccent,\n                                onTap: onMinimize,\n                                icon: Icons.remove,\n                              ),\n                              const SizedBox(width: 8),\n                              _WindowControl(\n                                color: Colors.greenAccent,\n                                onTap: onMaximize,\n                                icon: windowData.isMaximized\n                                    ? Icons.close_fullscreen\n                                    : Icons.fullscreen,\n                              ),\n                              const SizedBox(width: 12),\n                              windowData.icon is IconData\n                                  ? Icon(\n                                      windowData.icon,\n                                      color: onSurfaceColor.withValues(\n                                        alpha: 0.7,\n                                      ),\n                                      size: 14,\n                                    )\n                                  : FaIcon(\n                                      windowData.icon,\n                                      color: onSurfaceColor.withValues(\n                                        alpha: 0.7,\n                                      ),\n                                      size: 12,\n                                    ),\n                              const SizedBox(width: 8),\n                              Text(\n                                windowData.title,\n                                style: GoogleFonts.inter(\n                                  color: onSurfaceColor.withValues(alpha: 0.9),\n                                  fontSize: 13,\n                                  fontWeight: FontWeight.w500,\n                                ),\n                              ),\n                              const Spacer(),\n                              const SizedBox(width: 60),\n                            ],\n                          ),\n                        ),\n                      ),\n                    ),\n                    Expanded(\n                      child: Container(\n                        color: surfaceColor.withValues(alpha: 0.9),\n                        child: windowData.content,\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n\n            // Resize Handles\n            if (!windowData.isMaximized) ...[\n              // Right Edge\n              Positioned(\n                right: 0,\n                top: 0,\n                bottom: 15,\n                width: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeLeftRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          (windowData.size.width + details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          ),\n                          windowData.size.height,\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ),\n              // Left Edge\n              Positioned(\n                left: 0,\n                top: 0,\n                bottom: 15,\n                width: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeLeftRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      final newWidth =\n                          (windowData.size.width - details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          );\n                      if (newWidth != windowData.size.width) {\n                        onSizeChanged(Size(newWidth, windowData.size.height));\n                        onPositionChanged(\n                          windowData.position + Offset(details.delta.dx, 0),\n                        );\n                      }\n                    },\n                  ),\n                ),\n              ),\n              // Bottom Edge\n              Positioned(\n                bottom: 0,\n                left: 0,\n                right: 15,\n                height: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpDown,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          windowData.size.width,\n                          (windowData.size.height + details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          ),\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ),\n              // Top Edge\n              Positioned(\n                top: 0,\n                left: 0,\n                right: 0,\n                height: 6,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpDown,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      final newHeight =\n                          (windowData.size.height - details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          );\n                      if (newHeight != windowData.size.height) {\n                        onSizeChanged(Size(windowData.size.width, newHeight));\n                        onPositionChanged(\n                          windowData.position + Offset(0, details.delta.dy),\n                        );\n                      }\n                    },\n                  ),\n                ),\n              ),\n              // Bottom Right Corner\n              Positioned(\n                right: 0,\n                bottom: 0,\n                width: 15,\n                height: 15,\n                child: MouseRegion(\n                  cursor: SystemMouseCursors.resizeUpLeftDownRight,\n                  child: GestureDetector(\n                    onPanUpdate: (details) {\n                      onSizeChanged(\n                        Size(\n                          (windowData.size.width + details.delta.dx).clamp(\n                            300.0,\n                            1200.0,\n                          ),\n                          (windowData.size.height + details.delta.dy).clamp(\n                            200.0,\n                            800.0,\n                          ),\n                        ),\n                      );\n                    },\n                    child: Container(\n                      color: Colors.transparent,\n                      child: const Icon(\n                        Icons.drag_handle,\n                        size: 12,\n                        color: Colors.white24,\n                      ),\n                    ),\n                  ),\n                ),\n              ),\n            ],\n          ],\n        ),\n      ),\n    );\n\n    if (windowData.isMaximized) {\n      return Positioned(\n        left: 0,\n        top: 35,\n        right: 0,\n        bottom: 90,\n        child: windowContent,\n      );\n    }\n\n    return Positioned(\n      left: windowData.position.dx,\n      top: windowData.position.dy,\n      child: windowContent,\n    );\n  }\n}\n\nclass _WindowControl extends StatefulWidget {\n  final Color color;\n  final VoidCallback onTap;\n  final IconData icon;\n\n  const _WindowControl({\n    required this.color,\n    required this.onTap,\n    required this.icon,\n  });\n\n  @override\n  State<_WindowControl> createState() => _WindowControlState();\n}\n\nclass _WindowControlState extends State<_WindowControl> {\n  bool _isHovered = false;\n\n  @override\n  Widget build(BuildContext context) {\n    return MouseRegion(\n      onEnter: (_) => setState(() => _isHovered = true),\n      onExit: (_) => setState(() => _isHovered = false),\n      child: GestureDetector(\n        onTap: widget.onTap,\n        child: Container(\n          width: 12,\n          height: 12,\n          decoration: BoxDecoration(\n            color: widget.color,\n            shape: BoxShape.circle,\n          ),\n          child: _isHovered\n              ? Center(child: Icon(widget.icon, size: 8, color: Colors.black54))\n              : null,\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/apps/contact_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'package:provider/provider.dart';\nimport '../models/config_model.dart';\n\nclass ContactApp extends StatelessWidget {\n  const ContactApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final config = context.watch<AppConfig>();\n\n    return Padding(\n      padding: const EdgeInsets.all(48.0),\n      child: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Text(\n              'Get in Touch',\n              style: GoogleFonts.outfit(\n                color: Colors.white,\n                fontSize: 36,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n            const SizedBox(height: 16),\n            Text(\n              \"I'm currently open to new opportunities and collaborations.\",\n              textAlign: TextAlign.center,\n              style: GoogleFonts.inter(color: Colors.white70, fontSize: 18),\n            ),\n            const SizedBox(height: 48),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: config.socials.map((social) {\n                return Padding(\n                  padding: const EdgeInsets.symmetric(horizontal: 12),\n                  child: _SocialButton(\n                    icon: _getSocialIcon(social.icon),\n                    label: social.name,\n                  ),\n                );\n              }).toList(),\n            ),\n            const SizedBox(height: 48),\n            Container(\n              constraints: const BoxConstraints(maxWidth: 500),\n              padding: const EdgeInsets.all(24),\n              decoration: BoxDecoration(\n                color: Colors.white.withOpacity(0.05),\n                borderRadius: BorderRadius.circular(20),\n                border: Border.all(color: Colors.white10),\n              ),\n              child: Column(\n                children: [\n                  _ContactField(label: 'Email', value: config.profile.email),\n                  const Divider(color: Colors.white10, height: 32),\n                  _ContactField(\n                    label: 'Location',\n                    value: config.profile.location,\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  dynamic _getSocialIcon(String iconName) {\n    switch (iconName) {\n      case 'github':\n        return FontAwesomeIcons.github;\n      case 'linkedin':\n        return FontAwesomeIcons.linkedin;\n      case 'twitter':\n        return FontAwesomeIcons.twitter;\n      case 'instagram':\n        return FontAwesomeIcons.instagram;\n      case 'facebook':\n        return FontAwesomeIcons.facebook;\n      case 'youtube':\n        return FontAwesomeIcons.youtube;\n      case 'tiktok':\n        return FontAwesomeIcons.tiktok;\n      default:\n        return FontAwesomeIcons.link;\n    }\n  }\n}\n\nclass _SocialButton extends StatelessWidget {\n  final dynamic icon;\n  final String label;\n\n  const _SocialButton({required this.icon, required this.label});\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        Container(\n          padding: const EdgeInsets.all(16),\n          decoration: BoxDecoration(\n            color: Colors.white.withOpacity(0.05),\n            shape: BoxShape.circle,\n            border: Border.all(color: Colors.white10),\n          ),\n          child: FaIcon(icon, color: Colors.white, size: 28),\n        ),\n        const SizedBox(height: 8),\n        Text(\n          label,\n          style: GoogleFonts.inter(color: Colors.white70, fontSize: 12),\n        ),\n      ],\n    );\n  }\n}\n\nclass _ContactField extends StatelessWidget {\n  final String label;\n  final String value;\n\n  const _ContactField({required this.label, required this.value});\n\n  @override\n  Widget build(BuildContext context) {\n    return Row(\n      mainAxisAlignment: MainAxisAlignment.spaceBetween,\n      children: [\n        Text(\n          label,\n          style: GoogleFonts.inter(color: Colors.white38, fontSize: 16),\n        ),\n        Text(\n          value,\n          style: GoogleFonts.inter(\n            color: Colors.white,\n            fontSize: 16,\n            fontWeight: FontWeight.w500,\n          ),\n        ),\n      ],\n    );\n  }\n}\n",
  "lib/apps/browser_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'dart:ui_web' as ui;\nimport 'dart:html' as html;\n\nclass BrowserApp extends StatefulWidget {\n  final String url;\n  const BrowserApp({super.key, required this.url});\n\n  @override\n  State<BrowserApp> createState() => _BrowserAppState();\n}\n\nclass _BrowserAppState extends State<BrowserApp> {\n  late String _viewId;\n\n  @override\n  void initState() {\n    super.initState();\n    _viewId = 'iframe-\${widget.url.hashCode}';\n\n    ui.platformViewRegistry.registerViewFactory(\n      _viewId,\n      (int viewId) => html.IFrameElement()\n        ..src = widget.url\n        ..style.border = 'none'\n        ..style.width = '100%'\n        ..style.height = '100%',\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      children: [\n        Container(\n          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n          color: Colors.black45,\n          child: Row(\n            children: [\n              const Icon(Icons.lock, size: 14, color: Colors.green),\n              const SizedBox(width: 8),\n              Expanded(\n                child: Container(\n                  padding: const EdgeInsets.symmetric(\n                    horizontal: 8,\n                    vertical: 4,\n                  ),\n                  decoration: BoxDecoration(\n                    color: Colors.white10,\n                    borderRadius: BorderRadius.circular(4),\n                  ),\n                  child: Text(\n                    widget.url,\n                    style: GoogleFonts.inter(\n                      color: Colors.white70,\n                      fontSize: 12,\n                    ),\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              const Icon(Icons.refresh, size: 16, color: Colors.white54),\n            ],\n          ),\n        ),\n        // Content\n        Expanded(child: HtmlElementView(viewType: _viewId)),\n      ],\n    );\n  }\n}\n",
  "lib/apps/terminal_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../models/config_model.dart';\n\nclass _FileNode {\n  final String name;\n  final String? content;\n  final bool isDirectory;\n  final Map<String, _FileNode>? children;\n  _FileNode? parent;\n\n  _FileNode({\n    required this.name,\n    this.content,\n    this.isDirectory = false,\n    this.children,\n  }) {\n    children?.values.forEach((child) => child.parent = this);\n  }\n}\n\nclass TerminalApp extends StatefulWidget {\n  const TerminalApp({super.key});\n\n  @override\n  State<TerminalApp> createState() => _TerminalAppState();\n}\n\nclass _TerminalAppState extends State<TerminalApp> {\n  final List<String> _history = [];\n  final TextEditingController _controller = TextEditingController();\n  final ScrollController _scrollController = ScrollController();\n  final FocusNode _focusNode = FocusNode();\n\n  late _FileNode _root;\n  late _FileNode _currentDir;\n\n  @override\n  void initState() {\n    super.initState();\n    _initFileSystem();\n\n    final config = context.read<AppConfig>();\n    _history.addAll([\n      '\${config.profile.systemName} v1.0.0 (tty1)',\n      'Welcome \${config.profile.terminalName}. Type \"help\" for a list of commands.',\n      '',\n    ]);\n\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (MediaQuery.of(context).size.width >= 600) {\n        _showNeofetch();\n        if (mounted) setState(() {});\n      }\n    });\n  }\n\n  void _initFileSystem() {\n    final config = context.read<AppConfig>();\n    _root = _FileNode(\n      name: '/',\n      isDirectory: true,\n      children: {\n        'home': _FileNode(\n          name: 'home',\n          isDirectory: true,\n          children: {\n            config.profile.terminalName: _FileNode(\n              name: config.profile.terminalName,\n              isDirectory: true,\n              children: {\n                'resume.txt': _FileNode(\n                  name: 'resume.txt',\n                  content:\n                      'Name: \${config.profile.name}\\nTitle: \${config.profile.title}\\nContact: me@example.com',\n                ),\n                'notes.txt': _FileNode(\n                  name: 'notes.txt',\n                  content: 'TODO: Build more awesome stuff.',\n                ),\n                'projects': _FileNode(\n                  name: 'projects',\n                  isDirectory: true,\n                  children: {\n                    'secret_project.txt': _FileNode(\n                      name: 'secret_project.txt',\n                      content: 'Shh! This is a secret.',\n                    ),\n                  },\n                ),\n              },\n            ),\n          },\n        ),\n        'etc': _FileNode(\n          name: 'etc',\n          isDirectory: true,\n          children: {\n            'config': _FileNode(name: 'config', content: 'system_mode=awesome'),\n          },\n        ),\n      },\n    );\n\n    _root.children!['home']!.parent = _root;\n    _root.children!['etc']!.parent = _root;\n\n    _currentDir =\n        _root.children!['home']!.children![config.profile.terminalName]!;\n  }\n\n  _FileNode? _getNode(String path) {\n    if (path.isEmpty) return _currentDir;\n\n    _FileNode current = path.startsWith('/') ? _root : _currentDir;\n    final parts = path.split('/').where((p) => p.isNotEmpty).toList();\n\n    for (final part in parts) {\n      if (part == '.') continue;\n      if (part == '~') {\n        final config = context.read<AppConfig>();\n        current =\n            _root.children!['home']!.children![config.profile.terminalName]!;\n        continue;\n      }\n      if (part == '..') {\n        current = current.parent ?? current;\n      } else {\n        if (!current.isDirectory ||\n            current.children == null ||\n            !current.children!.containsKey(part)) {\n          return null;\n        }\n        current = current.children![part]!;\n      }\n    }\n    return current;\n  }\n\n  String _getAbsolutePath(_FileNode node) {\n    if (node == _root) return '/';\n    final List<String> parts = [];\n    _FileNode? current = node;\n    while (current != null && current != _root) {\n      parts.insert(0, current.name);\n      current = current.parent;\n    }\n    return '/\${parts.join('/')}';\n  }\n\n  void _showNeofetch() {\n    final config = context.read<AppConfig>();\n    _history.addAll([\n      '            .-/+oossssoo+/-.               \${config.profile.terminalName}@\${config.profile.systemName}',\n      '        `:+ssssssssssssssssss+:`           ------------',\n      '      -+ssssssssssssssssssyyssss+-         OS: \${config.profile.systemName} 1.0.0 x86_64',\n      '    .ossssssssssssssssssdMMMNysssso.       Host:  \${config.profile.systemName}',\n      '   /ssssssssssshdmmNNmmyNMMMMhssssss/      Kernel: 5.15.0-generic',\n      '  +ssssssssshmydMMMMMMMNddddyssssssss+     Uptime: 2 hours, 42 mins',\n      ' /sssssssshNMMMyhhyyyyhmNMMMNhssssssss/    Packages: 1337 (dpkg)',\n      '.ssssssssdMMMMMMNdyysssdmMMMMMysssssssso.  Shell: zsh 5.8.1',\n      'osssssssNMMMMMMMMMMMMMMMMMMMMMysssssssso   Resolution: 1920x1080',\n      'osssssssNMMMMMMMMMMMMMMMMMMMMMysssssssso   DE: \${config.profile.systemName}-DE',\n      'osssssssNMMMMMMMMmhyyyyyyhmMMMhssssssso    WM: fyrWM',\n      '.ssssssssdMMMMMMNdyysssssdmMMMysssssssso.  Theme: Glassmorphic-Dark',\n      ' /sssssssshNMMMyhhyyyyhdNMMMNhssssssss/    Icons: Material-Rounded',\n      '  +ssssssssshmydMMMMMMMNddddyssssssss+     Terminal: fyrTerm',\n      '   /ssssssssssshdmmNNmmyNMMMMhssssss/      CPU: Virtual Core (4) @ 2.4GHz',\n      '    .ossssssssssssssssssdMMMNysssso.       GPU: SwiftShader',\n      '      -+ssssssssssssssssssyyssss+-         Memory: 2048MiB / 8192MiB',\n      '        `:+ssssssssssssssssss+:`',\n      '            .-/+oossssoo+/-.',\n    ]);\n  }\n\n  void _handleCommand(String input) {\n    final config = context.read<AppConfig>();\n    final promptPath = _getAbsolutePath(\n      _currentDir,\n    ).replaceFirst('/home/\${config.profile.terminalName}', '~');\n\n    setState(() {\n      _history.add(\n        '\${config.profile.terminalName}@\${config.profile.systemName}:\$promptPath\\\$ \$input',\n      );\n\n      final parts = input.trim().split(' ');\n      final cmd = parts[0].toLowerCase();\n      final args = parts.length > 1 ? parts.sublist(1) : <String>[];\n\n      switch (cmd) {\n        case 'neofetch':\n          _showNeofetch();\n          break;\n        case 'help':\n          _history.add(\n            'Available commands: help, clear, whoami, date, uname, neofetch, pwd, ls, cd, cat',\n          );\n          break;\n        case 'clear':\n          _history.clear();\n          return;\n        case 'pwd':\n          _history.add(_getAbsolutePath(_currentDir));\n          break;\n        case 'ls':\n          final targetPath = args.isNotEmpty ? args[0] : '';\n          final node = _getNode(targetPath);\n          if (node == null) {\n            _history.add(\n              'ls: cannot access \\'\$targetPath\\': No such file or directory',\n            );\n          } else if (!node.isDirectory) {\n            _history.add(node.name);\n          } else {\n            if (node.children == null || node.children!.isEmpty) {\n              // Empty dir\n            } else {\n              final files = node.children!.values\n                  .map((c) => c.isDirectory ? '\${c.name}/' : c.name)\n                  .join('  ');\n              _history.add(files);\n            }\n          }\n          break;\n        case 'cd':\n          final targetPath = args.isNotEmpty ? args[0] : '~';\n          final node = _getNode(targetPath);\n          if (node == null) {\n            _history.add('cd: \$targetPath: No such file or directory');\n          } else if (!node.isDirectory) {\n            _history.add('cd: \$targetPath: Not a directory');\n          } else {\n            _currentDir = node;\n          }\n          break;\n        case 'cat':\n          if (args.isEmpty) {\n            _history.add('cat: missing operand');\n          } else {\n            final node = _getNode(args[0]);\n            if (node == null) {\n              _history.add('cat: \${args[0]}: No such file or directory');\n            } else if (node.isDirectory) {\n              _history.add('cat: \${args[0]}: Is a directory');\n            } else {\n              _history.addAll(node.content?.split('\\n') ?? []);\n            }\n          }\n          break;\n        case 'whoami':\n          _history.add(config.profile.terminalName);\n          break;\n        case 'date':\n          _history.add(DateTime.now().toString());\n          break;\n        case 'uname':\n          _history.add('\${config.profile.systemName} 5.15.0-generic x86_64');\n          break;\n        case '':\n          break;\n        default:\n          _history.add('Command not found: \$cmd');\n      }\n      _history.add('');\n    });\n\n    _controller.clear();\n    _focusNode.requestFocus();\n    Future.delayed(const Duration(milliseconds: 100), () {\n      if (_scrollController.hasClients) {\n        _scrollController.animateTo(\n          _scrollController.position.maxScrollExtent,\n          duration: const Duration(milliseconds: 200),\n          curve: Curves.easeOut,\n        );\n      }\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final config = context.watch<AppConfig>();\n    final promptPath = _getAbsolutePath(\n      _currentDir,\n    ).replaceFirst('/home/\${config.profile.terminalName}', '~');\n\n    return GestureDetector(\n      onTap: () => _focusNode.requestFocus(),\n      child: Container(\n        color: isDark ? Colors.black : Colors.black87,\n        padding: const EdgeInsets.all(12),\n        child: SingleChildScrollView(\n          controller: _scrollController,\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              ..._history.map(\n                (line) => Text(\n                  line,\n                  style: GoogleFonts.firaCode(\n                    color: Colors.greenAccent,\n                    fontSize: 14,\n                  ),\n                ),\n              ),\n              Row(\n                children: [\n                  Text(\n                    '\${config.profile.terminalName}@\${config.profile.systemName}:\$promptPath\\\$ ',\n                    style: GoogleFonts.firaCode(\n                      color: Colors.greenAccent,\n                      fontSize: 14,\n                    ),\n                  ),\n                  Expanded(\n                    child: TextField(\n                      controller: _controller,\n                      focusNode: _focusNode,\n                      autofocus: true,\n                      cursorColor: Colors.greenAccent,\n                      style: GoogleFonts.firaCode(\n                        color: Colors.greenAccent,\n                        fontSize: 14,\n                      ),\n                      decoration: const InputDecoration(\n                        border: InputBorder.none,\n                        isDense: true,\n                        contentPadding: EdgeInsets.zero,\n                      ),\n                      onSubmitted: _handleCommand,\n                    ),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/apps/file_explorer_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../system_controller.dart';\nimport 'resume_app.dart';\n\nclass FileExplorerApp extends StatefulWidget {\n  const FileExplorerApp({super.key});\n\n  @override\n  State<FileExplorerApp> createState() => _FileExplorerAppState();\n}\n\nclass _FileExplorerAppState extends State<FileExplorerApp> {\n  String _currentPath = 'Home';\n\n  final Map<String, List<Map<String, dynamic>>> _folders = {\n    'Home': [\n      {\n        'name': 'Projects',\n        'icon': Icons.folder,\n        'color': Colors.blue,\n        'isFolder': true,\n      },\n      {\n        'name': 'Music',\n        'icon': Icons.folder,\n        'color': Colors.blue,\n        'isFolder': true,\n      },\n      {\n        'name': 'resume.pdf',\n        'icon': Icons.picture_as_pdf,\n        'color': Colors.red,\n        'isFolder': false,\n      },\n    ],\n    'Projects': [\n      {\n        'name': 'libretrac.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://libretrac.site',\n        'external': true,\n      },\n      {\n        'name': 'welledumacated.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://welledumacated.dev',\n        'external': true,\n      },\n      {\n        'name': 'bybl.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://bybl.dev',\n        'external': true,\n      },\n      {\n        'name': 'theolivebranch.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://theolivebranch.press',\n        'external': true,\n      },\n      {\n        'name': 'fyr.html',\n        'icon': Icons.html,\n        'color': Colors.orange,\n        'isFolder': false,\n        'url': 'https://fyr.software',\n        'external': true,\n      },\n    ],\n    'Music': [\n      {\n        'name': 'archbtw.wav',\n        'icon': Icons.music_note,\n        'color': Colors.purple,\n        'isFolder': false,\n        'url': 'https://archBTW.sh',\n        'external': true,\n      },\n      {\n        'name': 'violetapparition.mp3',\n        'icon': Icons.music_note,\n        'color': Colors.purple,\n        'isFolder': false,\n        'url': 'https://violetapparition.com',\n        'external': true,\n      },\n    ],\n  };\n\n  void _navigateTo(String folder) {\n    if (_folders.containsKey(folder)) {\n      setState(() {\n        _currentPath = folder;\n      });\n    }\n  }\n\n  void _goBack() {\n    if (_currentPath != 'Home') {\n      setState(() {\n        _currentPath = 'Home';\n      });\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final files = _folders[_currentPath] ?? [];\n    final isMobile = MediaQuery.of(context).size.width < 600;\n\n    return Material(\n      color: Colors.transparent,\n      child: Column(\n        children: [\n          Container(\n            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n            color: Colors.white.withValues(alpha: 0.05),\n            child: Row(\n              children: [\n                IconButton(\n                  icon: const Icon(\n                    Icons.arrow_back,\n                    size: 18,\n                    color: Colors.white54,\n                  ),\n                  onPressed: _currentPath == 'Home' ? null : _goBack,\n                ),\n                const SizedBox(width: 8),\n                const Icon(\n                  Icons.arrow_forward,\n                  size: 18,\n                  color: Colors.white54,\n                ),\n                const SizedBox(width: 24),\n                Text(\n                  'Home > \$_currentPath',\n                  style: GoogleFonts.inter(color: Colors.white70, fontSize: 13),\n                ),\n                const Spacer(),\n                const Icon(Icons.search, size: 18, color: Colors.white54),\n                const SizedBox(width: 16),\n                const Icon(Icons.view_module, size: 18, color: Colors.white54),\n              ],\n            ),\n          ),\n          // Content\n          Expanded(\n            child: GridView.builder(\n              padding: const EdgeInsets.all(24),\n              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(\n                crossAxisCount: isMobile ? 3 : 6,\n                crossAxisSpacing: 20,\n                mainAxisSpacing: 20,\n              ),\n              itemCount: files.length,\n              itemBuilder: (context, index) {\n                final file = files[index];\n                return InkWell(\n                  onTap: () {\n                    if (file['isFolder'] == true) {\n                      _navigateTo(file['name'] as String);\n                    } else if (file['name'] == 'resume.pdf') {\n                      context.read<SystemController>().openApp(\n                        'resume',\n                        'Resume',\n                        const ResumeApp(),\n                        Icons.picture_as_pdf,\n                      );\n                    } else if (file['url'] != null) {\n                      final url = file['url'] as String;\n                      context.read<SystemController>().openApp(\n                        file['name'] as String,\n                        file['name'] as String,\n                        null,\n                        null,\n                        url: url,\n                      );\n                    }\n                  },\n                  child: Column(\n                    children: [\n                      Icon(\n                        file['icon'] as IconData,\n                        color: file['color'] as Color,\n                        size: 48,\n                      ),\n                      const SizedBox(height: 8),\n                      Text(\n                        file['name'] as String,\n                        style: GoogleFonts.inter(\n                          color: Colors.white70,\n                          fontSize: 12,\n                        ),\n                        textAlign: TextAlign.center,\n                        maxLines: 1,\n                        overflow: TextOverflow.ellipsis,\n                      ),\n                    ],\n                  ),\n                );\n              },\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n",
  "lib/apps/settings_app.dart": "import 'package:flutter/material.dart';\nimport 'dart:convert';\nimport 'package:file_picker/file_picker.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport '../system_settings.dart';\n\nclass SettingsApp extends StatelessWidget {\n  const SettingsApp({super.key});\n\n  Future<void> _pickWallpaper(SystemSettings settings) async {\n    FilePickerResult? result = await FilePicker.pickFiles(\n      type: FileType.image,\n      allowMultiple: false,\n      withData: true,\n    );\n\n    if (result != null && result.files.first.bytes != null) {\n      final bytes = result.files.first.bytes!;\n      final base64String = 'data:image/png;base64,\${base64.encode(bytes)}';\n      settings.setWallpaper(base64String);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final settings = context.watch<SystemSettings>();\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return SingleChildScrollView(\n      padding: const EdgeInsets.all(32),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\n            'Appearance',\n            style: GoogleFonts.outfit(\n              color: onSurfaceColor,\n              fontSize: 28,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 32),\n\n          _SettingSection(\n            title: 'Theme Mode',\n            child: Row(\n              children: [\n                _ThemeOption(\n                  label: 'Dark',\n                  isSelected: settings.isDarkMode,\n                  onTap: () => settings.setDarkMode(true),\n                  color: Colors.black,\n                ),\n                const SizedBox(width: 20),\n                _ThemeOption(\n                  label: 'Light',\n                  isSelected: !settings.isDarkMode,\n                  onTap: () => settings.setDarkMode(false),\n                  color: Colors.white,\n                ),\n              ],\n            ),\n          ),\n\n          const SizedBox(height: 40),\n\n          _SettingSection(\n            title: 'Accent Color',\n            child: Wrap(\n              spacing: 12,\n              children: [\n                _ColorCircle(\n                  color: Colors.blue,\n                  isSelected: settings.accentColor.value == Colors.blue.value,\n                  onTap: () => settings.setAccentColor(Colors.blue),\n                ),\n                _ColorCircle(\n                  color: Colors.purple,\n                  isSelected: settings.accentColor.value == Colors.purple.value,\n                  onTap: () => settings.setAccentColor(Colors.purple),\n                ),\n                _ColorCircle(\n                  color: Colors.green,\n                  isSelected: settings.accentColor.value == Colors.green.value,\n                  onTap: () => settings.setAccentColor(Colors.green),\n                ),\n                _ColorCircle(\n                  color: Colors.orange,\n                  isSelected: settings.accentColor.value == Colors.orange.value,\n                  onTap: () => settings.setAccentColor(Colors.orange),\n                ),\n                _ColorCircle(\n                  color: Colors.pink,\n                  isSelected: settings.accentColor.value == Colors.pink.value,\n                  onTap: () => settings.setAccentColor(Colors.pink),\n                ),\n              ],\n            ),\n          ),\n\n          const SizedBox(height: 40),\n\n          _SettingSection(\n            title: 'Wallpaper',\n            child: Wrap(\n              spacing: 16,\n              runSpacing: 16,\n              children: [\n                _WallpaperThumb(\n                  path: 'assets/wallpaper.jpg',\n                  isSelected: settings.wallpaperPath == 'assets/wallpaper.jpg',\n                  onTap: () => settings.setWallpaper('assets/wallpaper.jpg'),\n                ),\n                _WallpaperThumb(\n                  path:\n                      'https://images.unsplash.com/photo-1477346611705-65d1883cee1e?q=80&w=1000',\n                  isSelected: settings.wallpaperPath.contains(\n                    'photo-1477346611705',\n                  ),\n                  onTap: () => settings.setWallpaper(\n                    'https://images.unsplash.com/photo-1477346611705-65d1883cee1e?q=80&w=1000',\n                  ),\n                ),\n                _WallpaperThumb(\n                  path:\n                      'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1000',\n                  isSelected: settings.wallpaperPath.contains(\n                    'photo-1464822759023',\n                  ),\n                  onTap: () => settings.setWallpaper(\n                    'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1000',\n                  ),\n                ),\n\n                GestureDetector(\n                  onTap: () => _pickWallpaper(settings),\n                  child: Container(\n                    width: 140,\n                    height: 80,\n                    decoration: BoxDecoration(\n                      color: onSurfaceColor.withOpacity(0.05),\n                      borderRadius: BorderRadius.circular(8),\n                      border: Border.all(\n                        color: onSurfaceColor.withOpacity(0.2),\n                        style: BorderStyle.solid,\n                      ),\n                    ),\n                    child: Column(\n                      mainAxisAlignment: MainAxisAlignment.center,\n                      children: [\n                        Icon(\n                          Icons.upload,\n                          color: onSurfaceColor.withOpacity(0.5),\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          'Upload New',\n                          style: GoogleFonts.inter(\n                            color: onSurfaceColor.withOpacity(0.5),\n                            fontSize: 11,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _SidebarItem extends StatelessWidget {\n  final IconData icon;\n  final String label;\n  final bool isSelected;\n\n  const _SidebarItem({\n    required this.icon,\n    required this.label,\n    this.isSelected = false,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),\n      color: isSelected ? onSurfaceColor.withOpacity(0.05) : Colors.transparent,\n      child: Row(\n        children: [\n          Icon(\n            icon,\n            color: isSelected\n                ? onSurfaceColor\n                : onSurfaceColor.withOpacity(0.5),\n            size: 18,\n          ),\n          const SizedBox(width: 12),\n          Text(\n            label,\n            style: GoogleFonts.inter(\n              color: isSelected\n                  ? onSurfaceColor\n                  : onSurfaceColor.withOpacity(0.5),\n              fontSize: 13,\n              fontWeight: isSelected ? FontWeight.w600 : FontWeight.w400,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _SettingSection extends StatelessWidget {\n  final String title;\n  final Widget child;\n\n  const _SettingSection({required this.title, required this.child});\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          title,\n          style: GoogleFonts.inter(\n            color: Theme.of(context).colorScheme.onSurface.withOpacity(0.5),\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        const SizedBox(height: 16),\n        child,\n      ],\n    );\n  }\n}\n\nclass _ThemeOption extends StatelessWidget {\n  final String label;\n  final bool isSelected;\n  final VoidCallback onTap;\n  final Color color;\n\n  const _ThemeOption({\n    required this.label,\n    required this.isSelected,\n    required this.onTap,\n    required this.color,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return GestureDetector(\n      onTap: onTap,\n      child: Column(\n        children: [\n          Container(\n            width: 80,\n            height: 60,\n            decoration: BoxDecoration(\n              color: color,\n              borderRadius: BorderRadius.circular(8),\n              border: Border.all(\n                color: isSelected\n                    ? Colors.blue\n                    : Theme.of(context).colorScheme.onSurface.withOpacity(0.2),\n                width: 2,\n              ),\n            ),\n          ),\n          const SizedBox(height: 8),\n          Text(\n            label,\n            style: GoogleFonts.inter(\n              color: Theme.of(context).colorScheme.onSurface.withOpacity(0.7),\n              fontSize: 12,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _ColorCircle extends StatelessWidget {\n  final Color color;\n  final bool isSelected;\n  final VoidCallback onTap;\n\n  const _ColorCircle({\n    required this.color,\n    required this.isSelected,\n    required this.onTap,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return GestureDetector(\n      onTap: onTap,\n      child: Container(\n        width: 32,\n        height: 32,\n        decoration: BoxDecoration(\n          color: color,\n          shape: BoxShape.circle,\n          border: Border.all(\n            color: isSelected\n                ? Theme.of(context).colorScheme.onSurface\n                : Colors.transparent,\n            width: 2,\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _WallpaperThumb extends StatelessWidget {\n  final String path;\n  final bool isSelected;\n  final VoidCallback onTap;\n\n  const _WallpaperThumb({\n    required this.path,\n    required this.isSelected,\n    required this.onTap,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return GestureDetector(\n      onTap: onTap,\n      child: Container(\n        width: 140,\n        height: 80,\n        decoration: BoxDecoration(\n          borderRadius: BorderRadius.circular(8),\n          border: Border.all(\n            color: isSelected ? Colors.blue : Colors.transparent,\n            width: 3,\n          ),\n          image: DecorationImage(\n            image: path.startsWith('assets')\n                ? AssetImage(path) as ImageProvider\n                : NetworkImage(path),\n            fit: BoxFit.cover,\n          ),\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/apps/resume_app.dart": "import 'package:flutter/material.dart';\nimport 'package:flutter/foundation.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:provider/provider.dart';\nimport 'package:pdf/pdf.dart';\nimport 'package:pdf/widgets.dart' as pw;\nimport 'package:printing/printing.dart';\nimport 'package:universal_html/html.dart' as html;\nimport '../models/config_model.dart';\n\nclass ResumeApp extends StatelessWidget {\n  const ResumeApp({super.key});\n\n  Future<void> _generatePdf(AppConfig config) async {\n    final pdf = pw.Document();\n\n    final theme = pw.ThemeData.withFont(\n      base: pw.Font.helvetica(),\n      bold: pw.Font.helveticaBold(),\n    );\n\n    final primaryColor = PdfColor.fromHex('#4B0082'); // Indigo/Deep Purple\n    final accentColor = PdfColor.fromHex('#E6E6FA'); // Lavender\n    final textColor = PdfColors.grey800;\n\n    pdf.addPage(\n      pw.MultiPage(\n        pageTheme: pw.PageTheme(\n          theme: theme,\n          margin: const pw.EdgeInsets.all(0),\n        ),\n        build: (pw.Context context) {\n          return [\n            // Header Section with background color\n            pw.Container(\n              padding: const pw.EdgeInsets.all(40),\n              color: primaryColor,\n              child: pw.Row(\n                crossAxisAlignment: pw.CrossAxisAlignment.center,\n                children: [\n                  pw.Expanded(\n                    child: pw.Column(\n                      crossAxisAlignment: pw.CrossAxisAlignment.start,\n                      children: [\n                        pw.Text(\n                          config.profile.name.toUpperCase(),\n                          style: pw.TextStyle(\n                            fontSize: 32,\n                            fontWeight: pw.FontWeight.bold,\n                            color: PdfColors.white,\n                            letterSpacing: 2,\n                          ),\n                        ),\n                        pw.SizedBox(height: 8),\n                        pw.Text(\n                          config.profile.title,\n                          style: pw.TextStyle(fontSize: 18, color: accentColor),\n                        ),\n                      ],\n                    ),\n                  ),\n                  pw.Column(\n                    crossAxisAlignment: pw.CrossAxisAlignment.end,\n                    children: [\n                      if (config.profile.email.isNotEmpty) ...[\n                        pw.Text(\n                          config.profile.email,\n                          style: const pw.TextStyle(\n                            color: PdfColors.white,\n                            fontSize: 12,\n                          ),\n                        ),\n                        pw.SizedBox(height: 4),\n                      ],\n                      if (config.profile.location.isNotEmpty) ...[\n                        pw.Text(\n                          config.profile.location,\n                          style: const pw.TextStyle(\n                            color: PdfColors.white,\n                            fontSize: 12,\n                          ),\n                        ),\n                        pw.SizedBox(height: 4),\n                      ],\n                      pw.Text(\n                        'github.com/archieBTW',\n                        style: const pw.TextStyle(\n                          color: PdfColors.white,\n                          fontSize: 12,\n                        ),\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n\n            // Body Content\n            pw.Padding(\n              padding: const pw.EdgeInsets.all(40),\n              child: pw.Row(\n                crossAxisAlignment: pw.CrossAxisAlignment.start,\n                children: [\n                  // Left Column: Experience & Education\n                  pw.Expanded(\n                    flex: 2,\n                    child: pw.Column(\n                      crossAxisAlignment: pw.CrossAxisAlignment.start,\n                      children: [\n                        _buildSectionHeader(\n                          'PROFESSIONAL EXPERIENCE',\n                          primaryColor,\n                        ),\n                        ...config.experience\n                            .map(\n                              (e) => pw.Column(\n                                crossAxisAlignment: pw.CrossAxisAlignment.start,\n                                children: [\n                                  pw.Row(\n                                    mainAxisAlignment:\n                                        pw.MainAxisAlignment.spaceBetween,\n                                    children: [\n                                      pw.Text(\n                                        e.role,\n                                        style: pw.TextStyle(\n                                          fontWeight: pw.FontWeight.bold,\n                                          fontSize: 13,\n                                          color: PdfColors.black,\n                                        ),\n                                      ),\n                                      pw.Text(\n                                        e.period,\n                                        style: pw.TextStyle(\n                                          color: primaryColor,\n                                          fontSize: 11,\n                                          fontWeight: pw.FontWeight.bold,\n                                        ),\n                                      ),\n                                    ],\n                                  ),\n                                  pw.SizedBox(height: 2),\n                                  pw.Text(\n                                    e.company,\n                                    style: pw.TextStyle(\n                                      fontStyle: pw.FontStyle.italic,\n                                      color: PdfColors.grey700,\n                                      fontSize: 11,\n                                    ),\n                                  ),\n                                  pw.SizedBox(height: 6),\n                                  pw.Text(\n                                    e.description,\n                                    style: pw.TextStyle(\n                                      fontSize: 11,\n                                      color: textColor,\n                                      lineSpacing: 1.5,\n                                    ),\n                                  ),\n                                  pw.SizedBox(height: 20),\n                                ],\n                              ),\n                            )\n                            .toList(),\n\n                        pw.SizedBox(height: 10),\n                        _buildSectionHeader('EDUCATION', primaryColor),\n                        ...config.education\n                            .map(\n                              (e) => pw.Column(\n                                crossAxisAlignment: pw.CrossAxisAlignment.start,\n                                children: [\n                                  pw.Row(\n                                    mainAxisAlignment:\n                                        pw.MainAxisAlignment.spaceBetween,\n                                    children: [\n                                      pw.Text(\n                                        e.school,\n                                        style: pw.TextStyle(\n                                          fontWeight: pw.FontWeight.bold,\n                                          fontSize: 12,\n                                        ),\n                                      ),\n                                      pw.Text(\n                                        e.period,\n                                        style: pw.TextStyle(\n                                          color: primaryColor,\n                                          fontSize: 11,\n                                        ),\n                                      ),\n                                    ],\n                                  ),\n                                  if (e.degree.isNotEmpty) ...[\n                                    pw.SizedBox(height: 2),\n                                    pw.Text(\n                                      e.degree,\n                                      style: pw.TextStyle(\n                                        fontStyle: pw.FontStyle.italic,\n                                        color: PdfColors.grey700,\n                                        fontSize: 11,\n                                      ),\n                                    ),\n                                  ],\n                                  pw.SizedBox(height: 16),\n                                ],\n                              ),\n                            )\n                            .toList(),\n                      ],\n                    ),\n                  ),\n\n                  pw.SizedBox(width: 40),\n\n                  // Right Column: Skills & Certifications\n                  pw.Expanded(\n                    flex: 1,\n                    child: pw.Column(\n                      crossAxisAlignment: pw.CrossAxisAlignment.start,\n                      children: [\n                        _buildSectionHeader('TECHNICAL SKILLS', primaryColor),\n                        ...config.skills\n                            .map(\n                              (skillGroup) => pw.Column(\n                                crossAxisAlignment: pw.CrossAxisAlignment.start,\n                                children: [\n                                  pw.Text(\n                                    skillGroup.category.toUpperCase(),\n                                    style: pw.TextStyle(\n                                      fontWeight: pw.FontWeight.bold,\n                                      fontSize: 11,\n                                      color: primaryColor,\n                                    ),\n                                  ),\n                                  pw.SizedBox(height: 6),\n                                  pw.Wrap(\n                                    spacing: 6,\n                                    runSpacing: 6,\n                                    children: skillGroup.items\n                                        .map(\n                                          (s) => pw.Container(\n                                            padding:\n                                                const pw.EdgeInsets.symmetric(\n                                                  horizontal: 8,\n                                                  vertical: 4,\n                                                ),\n                                            decoration: pw.BoxDecoration(\n                                              color: accentColor,\n                                              borderRadius:\n                                                  const pw.BorderRadius.all(\n                                                    pw.Radius.circular(4),\n                                                  ),\n                                            ),\n                                            child: pw.Text(\n                                              s,\n                                              style: pw.TextStyle(\n                                                fontSize: 9,\n                                                color: primaryColor,\n                                              ),\n                                            ),\n                                          ),\n                                        )\n                                        .toList(),\n                                  ),\n                                  pw.SizedBox(height: 16),\n                                ],\n                              ),\n                            )\n                            .toList(),\n\n                        if (config.certifications.isNotEmpty) ...[\n                          pw.SizedBox(height: 10),\n                          _buildSectionHeader('CERTIFICATIONS', primaryColor),\n                          pw.Wrap(\n                            spacing: 6,\n                            runSpacing: 6,\n                            children: config.certifications\n                                .map(\n                                  (c) => pw.Container(\n                                    padding: const pw.EdgeInsets.symmetric(\n                                      horizontal: 8,\n                                      vertical: 4,\n                                    ),\n                                    decoration: const pw.BoxDecoration(\n                                      color: PdfColors.grey200,\n                                      borderRadius: pw.BorderRadius.all(\n                                        pw.Radius.circular(4),\n                                      ),\n                                    ),\n                                    child: pw.Text(\n                                      c,\n                                      style: const pw.TextStyle(fontSize: 10),\n                                    ),\n                                  ),\n                                )\n                                .toList(),\n                          ),\n                        ],\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ];\n        },\n      ),\n    );\n\n    final bytes = await pdf.save();\n    final filename =\n        '\${config.profile.name.toLowerCase().replaceAll(' ', '_')}_resume.pdf';\n\n    if (kIsWeb) {\n      final blob = html.Blob([bytes], 'application/pdf');\n      final url = html.Url.createObjectUrlFromBlob(blob);\n      final anchor = html.document.createElement('a') as html.AnchorElement\n        ..href = url\n        ..style.display = 'none'\n        ..download = filename;\n      html.document.body?.children.add(anchor);\n      anchor.click();\n      html.document.body?.children.remove(anchor);\n      html.Url.revokeObjectUrl(url);\n    } else {\n      await Printing.sharePdf(bytes: bytes, filename: filename);\n    }\n  }\n\n  pw.Widget _buildSectionHeader(String title, PdfColor color) {\n    return pw.Column(\n      crossAxisAlignment: pw.CrossAxisAlignment.start,\n      children: [\n        pw.Text(\n          title,\n          style: pw.TextStyle(\n            fontSize: 14,\n            fontWeight: pw.FontWeight.bold,\n            color: color,\n            letterSpacing: 1.2,\n          ),\n        ),\n        pw.SizedBox(height: 4),\n        pw.Container(height: 2, width: 30, color: color),\n        pw.SizedBox(height: 16),\n      ],\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final config = context.watch<AppConfig>();\n\n    final List<Color> categoryColors = [\n      const Color(0xFFE6E6FA), // Lavender\n      const Color(0xFFD4F1F4), // Soft Blue\n      const Color(0xFFE2F0CB), // Soft Green\n      const Color(0xFFFFDAB9), // Soft Orange\n      const Color(0xFFFDE8E9), // Soft Pink\n    ];\n\n    return Scaffold(\n      backgroundColor: Colors.transparent,\n      floatingActionButton: FloatingActionButton(\n        onPressed: () => _generatePdf(config),\n        tooltip: 'Download PDF',\n        child: const Icon(Icons.picture_as_pdf),\n      ),\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.all(40),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Row(\n              children: [\n                CircleAvatar(\n                  radius: 40,\n                  backgroundImage: AssetImage(config.profile.profilePic),\n                ),\n                const SizedBox(width: 24),\n                Expanded(\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        config.profile.name,\n                        style: GoogleFonts.outfit(\n                          color: Theme.of(context).colorScheme.onSurface,\n                          fontSize: 32,\n                          fontWeight: FontWeight.bold,\n                        ),\n                      ),\n                      Text(\n                        config.profile.title,\n                        style: GoogleFonts.inter(\n                          color: Theme.of(\n                            context,\n                          ).colorScheme.onSurface.withValues(alpha: 0.7),\n                          fontSize: 16,\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 40),\n            _Section(\n              title: 'Experience',\n              children: config.experience\n                  .map(\n                    (item) => _ExperienceItem(\n                      company: item.company,\n                      role: item.role,\n                      period: item.period,\n                      description: item.description,\n                    ),\n                  )\n                  .toList(),\n            ),\n            const SizedBox(height: 32),\n            if (config.education.isNotEmpty) ...[\n              _Section(\n                title: 'Education',\n                children: config.education\n                    .map(\n                      (item) => _EducationItem(\n                        school: item.school,\n                        degree: item.degree,\n                        period: item.period,\n                      ),\n                    )\n                    .toList(),\n              ),\n              const SizedBox(height: 32),\n            ],\n            if (config.certifications.isNotEmpty) ...[\n              _Section(\n                title: 'Certifications',\n                children: [\n                  Wrap(\n                    spacing: 12,\n                    runSpacing: 12,\n                    children: config.certifications\n                        .map(\n                          (cert) => _SkillChip(\n                            label: cert,\n                            outlineColor: Theme.of(\n                              context,\n                            ).colorScheme.onSurface.withValues(alpha: 0.2),\n                          ),\n                        )\n                        .toList(),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 32),\n            ],\n            _Section(\n              title: 'Skills',\n              children: config.skills.asMap().entries.map((entry) {\n                final index = entry.key;\n                final skillGroup = entry.value;\n                final color = categoryColors[index % categoryColors.length];\n\n                return Padding(\n                  padding: const EdgeInsets.only(bottom: 16),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        skillGroup.category,\n                        style: GoogleFonts.inter(\n                          color: Theme.of(context).colorScheme.onSurface,\n                          fontSize: 14,\n                          fontWeight: FontWeight.w600,\n                        ),\n                      ),\n                      const SizedBox(height: 8),\n                      Wrap(\n                        spacing: 8,\n                        runSpacing: 8,\n                        children: skillGroup.items\n                            .map(\n                              (skill) =>\n                                  _SkillChip(label: skill, outlineColor: color),\n                            )\n                            .toList(),\n                      ),\n                    ],\n                  ),\n                );\n              }).toList(),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _Section extends StatelessWidget {\n  final String title;\n  final List<Widget> children;\n\n  const _Section({required this.title, required this.children});\n\n  @override\n  Widget build(BuildContext context) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          title.toUpperCase(),\n          style: GoogleFonts.inter(\n            color: Theme.of(context).colorScheme.primary,\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n            letterSpacing: 1.2,\n          ),\n        ),\n        Divider(\n          color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.1),\n          height: 24,\n        ),\n        ...children,\n      ],\n    );\n  }\n}\n\nclass _ExperienceItem extends StatelessWidget {\n  final String company;\n  final String role;\n  final String period;\n  final String description;\n\n  const _ExperienceItem({\n    required this.company,\n    required this.role,\n    required this.period,\n    required this.description,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: const EdgeInsets.only(bottom: 24),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Expanded(\n                child: Text(\n                  role,\n                  style: GoogleFonts.inter(\n                    color: Theme.of(context).colorScheme.onSurface,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              Text(\n                period,\n                style: GoogleFonts.inter(\n                  color: Theme.of(\n                    context,\n                  ).colorScheme.onSurface.withValues(alpha: 0.5),\n                  fontSize: 14,\n                ),\n              ),\n            ],\n          ),\n          Text(\n            company,\n            style: GoogleFonts.inter(\n              color: Theme.of(\n                context,\n              ).colorScheme.onSurface.withValues(alpha: 0.7),\n              fontSize: 16,\n            ),\n          ),\n          const SizedBox(height: 8),\n          Text(\n            description,\n            style: GoogleFonts.inter(\n              color: Theme.of(\n                context,\n              ).colorScheme.onSurface.withValues(alpha: 0.5),\n              fontSize: 14,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _SkillChip extends StatelessWidget {\n  final String label;\n  final Color outlineColor;\n\n  const _SkillChip({\n    required this.label,\n    this.outlineColor = const Color.fromARGB(255, 114, 64, 127),\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n      decoration: BoxDecoration(\n        color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.05),\n        borderRadius: BorderRadius.circular(20),\n        border: Border.all(\n          color: Color.fromARGB(255, 114, 64, 127),\n          width: 0.5,\n        ),\n      ),\n      child: Text(\n        label,\n        style: GoogleFonts.inter(\n          color: Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.7),\n          fontSize: 14,\n          fontWeight: FontWeight.w500,\n        ),\n      ),\n    );\n  }\n}\n\nclass _EducationItem extends StatelessWidget {\n  final String school;\n  final String degree;\n  final String period;\n\n  const _EducationItem({\n    required this.school,\n    required this.degree,\n    required this.period,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: const EdgeInsets.only(bottom: 24),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            mainAxisAlignment: MainAxisAlignment.spaceBetween,\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Expanded(\n                child: Text(\n                  school,\n                  style: GoogleFonts.inter(\n                    color: Theme.of(context).colorScheme.onSurface,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n              const SizedBox(width: 8),\n              Text(\n                period,\n                style: GoogleFonts.inter(\n                  color: Theme.of(\n                    context,\n                  ).colorScheme.onSurface.withValues(alpha: 0.5),\n                  fontSize: 14,\n                ),\n              ),\n            ],\n          ),\n          if (degree.isNotEmpty) ...[\n            const SizedBox(height: 4),\n            Text(\n              degree,\n              style: GoogleFonts.inter(\n                color: Theme.of(\n                  context,\n                ).colorScheme.onSurface.withValues(alpha: 0.7),\n                fontSize: 16,\n              ),\n            ),\n          ],\n        ],\n      ),\n    );\n  }\n}\n",
  "lib/apps/code_editor_app.dart": "import 'package:flutter/material.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'package:flutter_highlight/flutter_highlight.dart';\nimport 'package:flutter_highlight/themes/vs2015.dart';\nimport '../generated/source_code.dart';\n\nclass FileNode {\n  final String name;\n  final String? fullPath;\n  final List<FileNode> children;\n\n  FileNode({required this.name, this.fullPath, List<FileNode>? children})\n    : children = children ?? [];\n\n  bool get isFile => fullPath != null;\n}\n\nclass CodeEditorApp extends StatefulWidget {\n  const CodeEditorApp({super.key});\n\n  @override\n  State<CodeEditorApp> createState() => _CodeEditorAppState();\n}\n\nclass _CodeEditorAppState extends State<CodeEditorApp> {\n  String? _selectedFile = 'lib/main.dart';\n\n  Widget _buildCodeViewer(String content, bool isDesktop) {\n    final lines = content.split('\\n');\n    final double fontSize = isDesktop ? 13 : 11;\n\n    return SelectionArea(\n      child: SingleChildScrollView(\n        padding: const EdgeInsets.all(16.0),\n        child: SingleChildScrollView(\n          scrollDirection: Axis.horizontal,\n          child: Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              // Line numbers\n              SelectionContainer.disabled(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.end,\n                  children: List.generate(lines.length, (index) {\n                    return Text(\n                      '\${index + 1}',\n                      style: GoogleFonts.jetBrainsMono(\n                        fontSize: fontSize,\n                        color: Colors.white38,\n                        height: 1.5,\n                      ),\n                    );\n                  }),\n                ),\n              ),\n              const SizedBox(width: 16),\n              // Code\n              HighlightView(\n                content,\n                language: 'dart',\n                theme: vs2015Theme,\n                padding: EdgeInsets.zero,\n                textStyle: GoogleFonts.jetBrainsMono(\n                  fontSize: fontSize,\n                  height: 1.5,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final screenWidth = MediaQuery.of(context).size.width;\n    final isDesktop = screenWidth >= 768.0;\n\n    final fileTreeWidget = _FileTreeWidget(\n      files: sourceCodeFiles,\n      selectedFile: _selectedFile,\n      onFileSelected: (path) {\n        setState(() {\n          _selectedFile = path;\n        });\n      },\n    );\n\n    final String? fileName = _selectedFile?.split('/').last;\n    final content = _selectedFile != null\n        ? sourceCodeFiles[_selectedFile!]\n        : null;\n\n    final codeViewerWidget = Container(\n      color: const Color(0xFF1E1E1E), // VSCode-like dark background\n      width: double.infinity,\n      height: double.infinity,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          if (fileName != null)\n            Container(\n              color: const Color(0xFF252526),\n              child: Row(\n                children: [\n                  Container(\n                    padding: const EdgeInsets.symmetric(\n                      horizontal: 16,\n                      vertical: 8,\n                    ),\n                    decoration: const BoxDecoration(\n                      color: Color(0xFF1E1E1E),\n                      border: Border(\n                        top: BorderSide(color: Colors.blueAccent, width: 2),\n                      ),\n                    ),\n                    child: Row(\n                      children: [\n                        Text(\n                          fileName,\n                          style: GoogleFonts.jetBrainsMono(\n                            color: Colors.white,\n                            fontSize: 13,\n                          ),\n                        ),\n                        const SizedBox(width: 8),\n                        const Icon(\n                          Icons.close,\n                          size: 14,\n                          color: Colors.white54,\n                        ),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          Expanded(\n            child: content == null\n                ? Center(\n                    child: Text(\n                      'Select a file to view its source code.',\n                      style: GoogleFonts.jetBrainsMono(color: Colors.white54),\n                    ),\n                  )\n                : _buildCodeViewer(content, isDesktop),\n          ),\n        ],\n      ),\n    );\n\n    return Scaffold(\n      backgroundColor: const Color(0xFF1E1E1E),\n      body: isDesktop\n          ? Row(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                SizedBox(width: 250, child: fileTreeWidget),\n                Expanded(child: codeViewerWidget),\n              ],\n            )\n          : Column(\n              children: [\n                Theme(\n                  data: Theme.of(\n                    context,\n                  ).copyWith(dividerColor: Colors.transparent),\n                  child: ExpansionTile(\n                    title: Text(\n                      'Explorer: \$_selectedFile',\n                      style: GoogleFonts.jetBrainsMono(\n                        color: Colors.white70,\n                        fontSize: 12,\n                      ),\n                      maxLines: 1,\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                    iconColor: Colors.white70,\n                    collapsedIconColor: Colors.white70,\n                    backgroundColor: const Color(0xFF252526),\n                    collapsedBackgroundColor: const Color(0xFF252526),\n                    children: [\n                      ConstrainedBox(\n                        constraints: BoxConstraints(\n                          maxHeight: MediaQuery.of(context).size.height * 0.4,\n                        ),\n                        child: _FileTreeWidget(\n                          files: sourceCodeFiles,\n                          selectedFile: _selectedFile,\n                          hideTitle: true,\n                          onFileSelected: (path) {\n                            setState(() {\n                              _selectedFile = path;\n                            });\n                          },\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n                Expanded(child: codeViewerWidget),\n              ],\n            ),\n    );\n  }\n}\n\nclass _FileTreeWidget extends StatelessWidget {\n  final Map<String, String> files;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n  final bool hideTitle;\n\n  const _FileTreeWidget({\n    required this.files,\n    this.selectedFile,\n    required this.onFileSelected,\n    this.hideTitle = false,\n  });\n\n  FileNode _buildTree() {\n    final root = FileNode(name: 'fyrWeb');\n    final libNode = FileNode(name: 'lib');\n    root.children.add(libNode);\n\n    for (final path in files.keys) {\n      final cleanPath = path.startsWith('lib/') ? path.substring(4) : path;\n      final parts = cleanPath.split('/');\n      var current = libNode;\n      for (var i = 0; i < parts.length; i++) {\n        final part = parts[i];\n        final isFile = i == parts.length - 1;\n\n        var child = current.children.cast<FileNode?>().firstWhere(\n          (n) => n!.name == part,\n          orElse: () => null,\n        );\n        if (child == null) {\n          child = FileNode(name: part, fullPath: isFile ? path : null);\n          current.children.add(child);\n        }\n        current = child;\n      }\n    }\n\n    _sortNode(libNode);\n    return root;\n  }\n\n  void _sortNode(FileNode node) {\n    node.children.sort((a, b) {\n      if (a.isFile && !b.isFile) return 1;\n      if (!a.isFile && b.isFile) return -1;\n      return a.name.compareTo(b.name);\n    });\n    for (final child in node.children) {\n      _sortNode(child);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final root = _buildTree();\n    return Container(\n      color: const Color(0xFF252526), // VSCode sidebar color\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          if (!hideTitle)\n            Padding(\n              padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),\n              child: Text(\n                'EXPLORER',\n                style: GoogleFonts.jetBrainsMono(\n                  fontSize: 11,\n                  color: Colors.white54,\n                  letterSpacing: 1.2,\n                  fontWeight: FontWeight.bold,\n                ),\n              ),\n            ),\n          Expanded(\n            child: ListView(\n              padding: EdgeInsets.zero,\n              children: [\n                _TreeNodeWidget(\n                  node: root,\n                  level: 0,\n                  selectedFile: selectedFile,\n                  onFileSelected: onFileSelected,\n                  initiallyExpanded: true,\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _TreeNodeWidget extends StatefulWidget {\n  final FileNode node;\n  final int level;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n  final bool initiallyExpanded;\n\n  const _TreeNodeWidget({\n    required this.node,\n    required this.level,\n    required this.selectedFile,\n    required this.onFileSelected,\n    this.initiallyExpanded = false,\n  });\n\n  @override\n  State<_TreeNodeWidget> createState() => _TreeNodeWidgetState();\n}\n\nclass _TreeNodeWidgetState extends State<_TreeNodeWidget> {\n  late bool _isExpanded;\n\n  @override\n  void initState() {\n    super.initState();\n    _isExpanded = widget.initiallyExpanded || widget.level <= 1;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    if (widget.node.isFile) {\n      final isSelected = widget.node.fullPath == widget.selectedFile;\n      return InkWell(\n        onTap: () => widget.onFileSelected(widget.node.fullPath!),\n        child: Container(\n          color: isSelected\n              ? Colors.white.withOpacity(0.1)\n              : Colors.transparent,\n          padding: EdgeInsets.only(\n            left: 16.0 + (widget.level * 12.0),\n            top: 4,\n            bottom: 4,\n            right: 8,\n          ),\n          child: Row(\n            children: [\n              const Icon(\n                Icons.insert_drive_file,\n                size: 14,\n                color: Colors.white70,\n              ),\n              const SizedBox(width: 6),\n              Expanded(\n                child: Text(\n                  widget.node.name,\n                  style: GoogleFonts.jetBrainsMono(\n                    fontSize: 13,\n                    color: isSelected ? Colors.white : Colors.white70,\n                  ),\n                  overflow: TextOverflow.ellipsis,\n                ),\n              ),\n            ],\n          ),\n        ),\n      );\n    } else {\n      return Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          InkWell(\n            onTap: () {\n              setState(() {\n                _isExpanded = !_isExpanded;\n              });\n            },\n            child: Container(\n              padding: EdgeInsets.only(\n                left: 8.0 + (widget.level * 12.0),\n                top: 4,\n                bottom: 4,\n                right: 8,\n              ),\n              child: Row(\n                children: [\n                  Icon(\n                    _isExpanded\n                        ? Icons.keyboard_arrow_down\n                        : Icons.keyboard_arrow_right,\n                    size: 16,\n                    color: Colors.white54,\n                  ),\n                  const SizedBox(width: 2),\n                  const Icon(\n                    Icons.folder,\n                    size: 14,\n                    color: Color(0xFF9E75FF),\n                  ), // purple folder\n                  const SizedBox(width: 6),\n                  Expanded(\n                    child: Text(\n                      widget.node.name,\n                      style: GoogleFonts.jetBrainsMono(\n                        fontSize: 13,\n                        color: Colors.white,\n                        fontWeight: FontWeight.w500,\n                      ),\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n          if (_isExpanded)\n            ...widget.node.children.map(\n              (child) => _TreeNodeWidget(\n                node: child,\n                level: widget.level + 1,\n                selectedFile: widget.selectedFile,\n                onFileSelected: widget.onFileSelected,\n              ),\n            ),\n        ],\n      );\n    }\n  }\n}\n",
  "lib/app_data.dart": "import 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'apps/contact_app.dart';\nimport 'apps/terminal_app.dart';\nimport 'apps/file_explorer_app.dart';\nimport 'apps/settings_app.dart';\nimport 'apps/resume_app.dart';\nimport 'apps/code_editor_app.dart';\nimport 'models/config_model.dart';\n\nclass AppInfo {\n  final String id;\n  final String title;\n  final Widget? content;\n  final dynamic icon;\n  final Color color;\n  final String? url;\n\n  AppInfo({\n    required this.id,\n    required this.title,\n    this.content,\n    required this.icon,\n    this.color = Colors.blue,\n    this.url,\n  });\n}\n\nList<AppInfo> getApps(AppConfig config) {\n  final List<AppInfo> systemApps = [\n    AppInfo(\n      id: 'resume',\n      title: 'Resume',\n      content: const ResumeApp(),\n      icon: Icons.description_outlined,\n      color: Colors.orange,\n    ),\n    AppInfo(\n      id: 'terminal',\n      title: 'Terminal',\n      content: const TerminalApp(),\n      icon: Icons.terminal,\n      color: Colors.black,\n    ),\n    AppInfo(\n      id: 'files',\n      title: 'File Explorer',\n      content: const FileExplorerApp(),\n      icon: Icons.folder,\n      color: Colors.blue,\n    ),\n    AppInfo(\n      id: 'code',\n      title: 'Source Code',\n      content: const CodeEditorApp(),\n      icon: Icons.code,\n      color: const Color(0xFF1E1E1E),\n    ),\n    AppInfo(\n      id: 'settings',\n      title: 'Settings',\n      content: const SettingsApp(),\n      icon: Icons.settings,\n      color: Colors.grey,\n    ),\n    AppInfo(\n      id: 'contact',\n      title: 'Contact Me',\n      content: const ContactApp(),\n      icon: Icons.mail_outline,\n      color: Colors.green,\n    ),\n  ];\n\n  final List<AppInfo> customApps = config.apps.map((app) {\n    return AppInfo(\n      id: app.id,\n      title: app.title,\n      url: app.url,\n      icon: _getIconData(app.icon),\n      color: Color(int.parse(app.color)),\n    );\n  }).toList();\n\n  return [...systemApps, ...customApps];\n}\n\ndynamic _getIconData(String iconName) {\n  switch (iconName) {\n    case 'computer':\n      return Icons.computer;\n    case 'code':\n      return Icons.code;\n    case 'language':\n      return Icons.language;\n    case 'github':\n      return FontAwesomeIcons.github;\n    case 'link':\n      return Icons.link;\n    case 'smartphone':\n      return Icons.smartphone;\n    case 'album':\n      return Icons.album;\n    case 'headphones':\n      return Icons.headphones;\n    case 'book':\n      return Icons.book;\n    case 'favorite':\n      return Icons.favorite;\n    case 'newspaper':\n      return Icons.newspaper;\n    default:\n      return Icons.apps;\n  }\n}\n",
  "lib/quick_settings.dart": "import 'package:flutter/material.dart';\nimport 'package:glass_kit/glass_kit.dart';\nimport 'package:google_fonts/google_fonts.dart';\n\nclass QuickSettings extends StatefulWidget {\n  const QuickSettings({super.key});\n\n  @override\n  State<QuickSettings> createState() => _QuickSettingsState();\n}\n\nclass _QuickSettingsState extends State<QuickSettings> {\n  bool wifi = true;\n  bool bluetooth = false;\n  bool airplaneMode = false;\n  bool nightShift = false;\n  double brightness = 0.8;\n  double volume = 0.6;\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = Theme.of(context).brightness == Brightness.dark;\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return GlassContainer.clearGlass(\n      width: 300,\n      height: 380,\n      borderRadius: BorderRadius.circular(16),\n      blur: 30,\n      color: isDark\n          ? Colors.black.withOpacity(0.6)\n          : Colors.white.withOpacity(0.8),\n      borderColor: onSurfaceColor.withOpacity(0.1),\n      child: Padding(\n        padding: const EdgeInsets.all(20.0),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Text(\n              'Control Center',\n              style: GoogleFonts.inter(\n                color: onSurfaceColor,\n                fontSize: 16,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n            const SizedBox(height: 20),\n            Wrap(\n              spacing: 12,\n              runSpacing: 12,\n              children: [\n                _QuickTile(\n                  icon: Icons.wifi,\n                  label: 'Wi-Fi',\n                  isOn: wifi,\n                  onTap: () => setState(() => wifi = !wifi),\n                ),\n                _QuickTile(\n                  icon: Icons.bluetooth,\n                  label: 'Bluetooth',\n                  isOn: bluetooth,\n                  onTap: () => setState(() => bluetooth = !bluetooth),\n                ),\n                _QuickTile(\n                  icon: Icons.airplanemode_active,\n                  label: 'Airplane',\n                  isOn: airplaneMode,\n                  onTap: () => setState(() => airplaneMode = !airplaneMode),\n                ),\n                _QuickTile(\n                  icon: Icons.nightlight_round,\n                  label: 'Night Shift',\n                  isOn: nightShift,\n                  onTap: () => setState(() => nightShift = !nightShift),\n                ),\n              ],\n            ),\n            const SizedBox(height: 24),\n            _SliderRow(\n              icon: Icons.brightness_high,\n              value: brightness,\n              onChanged: (v) => setState(() => brightness = v),\n            ),\n            const SizedBox(height: 16),\n            _SliderRow(\n              icon: Icons.volume_up,\n              value: volume,\n              onChanged: (v) => setState(() => volume = v),\n            ),\n            const Spacer(),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Text(\n                  'Battery: 84%',\n                  style: GoogleFonts.inter(\n                    color: onSurfaceColor.withOpacity(0.5),\n                    fontSize: 12,\n                  ),\n                ),\n                const Icon(Icons.battery_4_bar, color: Colors.green, size: 16),\n              ],\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _QuickTile extends StatelessWidget {\n  final IconData icon;\n  final String label;\n  final bool isOn;\n  final VoidCallback onTap;\n\n  const _QuickTile({\n    required this.icon,\n    required this.label,\n    required this.isOn,\n    required this.onTap,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return GestureDetector(\n      onTap: onTap,\n      child: Container(\n        width: 120,\n        padding: const EdgeInsets.all(12),\n        decoration: BoxDecoration(\n          color: isOn\n              ? Theme.of(context).colorScheme.primary.withOpacity(0.8)\n              : onSurfaceColor.withOpacity(0.05),\n          borderRadius: BorderRadius.circular(12),\n        ),\n        child: Row(\n          children: [\n            Icon(icon, color: isOn ? Colors.white : onSurfaceColor, size: 18),\n            const SizedBox(width: 8),\n            Text(\n              label,\n              style: GoogleFonts.inter(\n                color: isOn ? Colors.white : onSurfaceColor,\n                fontSize: 12,\n                fontWeight: FontWeight.w500,\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _SliderRow extends StatelessWidget {\n  final IconData icon;\n  final double value;\n  final ValueChanged<double> onChanged;\n\n  const _SliderRow({\n    required this.icon,\n    required this.value,\n    required this.onChanged,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final onSurfaceColor = Theme.of(context).colorScheme.onSurface;\n\n    return Row(\n      children: [\n        Icon(icon, color: onSurfaceColor.withOpacity(0.5), size: 18),\n        const SizedBox(width: 12),\n        Expanded(\n          child: SliderTheme(\n            data: SliderTheme.of(context).copyWith(\n              trackHeight: 20,\n              thumbShape: SliderComponentShape.noThumb,\n              overlayShape: SliderComponentShape.noOverlay,\n              activeTrackColor: onSurfaceColor.withOpacity(0.2),\n              inactiveTrackColor: onSurfaceColor.withOpacity(0.05),\n            ),\n            child: Slider(value: value, onChanged: onChanged),\n          ),\n        ),\n      ],\n    );\n  }\n}\n",
  "lib/app_menu.dart": "import 'package:flutter/material.dart';\nimport 'package:glass_kit/glass_kit.dart';\nimport 'package:google_fonts/google_fonts.dart';\nimport 'app_data.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\nimport 'package:provider/provider.dart';\nimport 'models/config_model.dart';\n\nclass AppMenu extends StatelessWidget {\n  final Function(String, String, Widget?, dynamic, {String? url}) onOpenApp;\n  final VoidCallback onClose;\n\n  const AppMenu({super.key, required this.onOpenApp, required this.onClose});\n\n  @override\n  Widget build(BuildContext context) {\n    return GlassContainer.clearGlass(\n      width: 250,\n      height: 500,\n      borderRadius: BorderRadius.circular(12),\n      blur: 30,\n      color: Colors.black.withOpacity(0.7),\n      borderColor: Colors.white.withOpacity(0.1),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Padding(\n            padding: const EdgeInsets.all(16.0),\n            child: Text(\n              'Applications',\n              style: GoogleFonts.inter(\n                color: Colors.white,\n                fontSize: 14,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n          ),\n          const Divider(color: Colors.white10, height: 1),\n          Expanded(\n            child: Consumer<AppConfig>(\n              builder: (context, config, child) {\n                final apps = getApps(config);\n                return ListView.builder(\n                  padding: const EdgeInsets.symmetric(vertical: 8),\n                  itemCount: apps.length,\n                  itemBuilder: (context, index) {\n                    final app = apps[index];\n                    return ListTile(\n                      dense: true,\n                      leading: app.icon is IconData\n                          ? Icon(app.icon, color: app.color, size: 18)\n                          : FaIcon(app.icon, color: app.color, size: 16),\n                      title: Text(\n                        app.title,\n                        style: GoogleFonts.inter(\n                          color: Colors.white,\n                          fontSize: 13,\n                        ),\n                      ),\n                      onTap: () {\n                        onOpenApp(\n                          app.id,\n                          app.title,\n                          app.content,\n                          app.icon,\n                          url: app.url,\n                        );\n                        onClose();\n                      },\n                    );\n                  },\n                );\n              },\n            ),\n          ),\n          const Divider(color: Colors.white10, height: 1),\n          ListTile(\n            dense: true,\n            leading: const Icon(\n              Icons.power_settings_new,\n              color: Colors.redAccent,\n              size: 18,\n            ),\n            title: Text(\n              'Shut Down...',\n              style: GoogleFonts.inter(color: Colors.white, fontSize: 13),\n            ),\n            onTap: onClose,\n          ),\n        ],\n      ),\n    );\n  }\n}\n",
  "lib/system_settings.dart": "import 'dart:convert';\nimport 'dart:typed_data';\nimport 'package:flutter/material.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\n\nclass SystemSettings extends ChangeNotifier {\n  late SharedPreferences _prefs;\n  bool _isInitialized = false;\n\n  bool _isDarkMode = true;\n  Color _accentColor = Colors.blue;\n  String _wallpaperPath = 'assets/wallpaper.jpg';\n  Uint8List? _wallpaperBytes;\n\n  bool get isDarkMode => _isDarkMode;\n  Color get accentColor => _accentColor;\n  String get wallpaperPath => _wallpaperPath;\n  Uint8List? get wallpaperBytes => _wallpaperBytes;\n  bool get isInitialized => _isInitialized;\n\n  SystemSettings() {\n    _loadSettings();\n  }\n\n  Future<void> _loadSettings() async {\n    _prefs = await SharedPreferences.getInstance();\n    _isDarkMode = _prefs.getBool('isDarkMode') ?? true;\n    _accentColor = Color(_prefs.getInt('accentColor') ?? Colors.blue.value);\n    _wallpaperPath =\n        _prefs.getString('wallpaperPath') ?? 'assets/wallpaper.jpg';\n    if (_wallpaperPath.startsWith('data:image')) {\n      _decodeWallpaper(_wallpaperPath);\n    }\n    _isInitialized = true;\n    notifyListeners();\n  }\n\n  void _decodeWallpaper(String path) {\n    try {\n      _wallpaperBytes = base64Decode(path.split(',').last);\n    } catch (e) {\n      _wallpaperBytes = null;\n    }\n  }\n\n  void setDarkMode(bool value) {\n    _isDarkMode = value;\n    _prefs.setBool('isDarkMode', value);\n    notifyListeners();\n  }\n\n  void setAccentColor(Color color) {\n    _accentColor = color;\n    _prefs.setInt('accentColor', color.value);\n    notifyListeners();\n  }\n\n  void setWallpaper(String path) {\n    _wallpaperPath = path;\n    if (path.startsWith('data:image')) {\n      _decodeWallpaper(path);\n    } else {\n      _wallpaperBytes = null;\n    }\n    _prefs.setString('wallpaperPath', path);\n    notifyListeners();\n  }\n}\n",
  "lib/system_controller.dart": "import 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\nimport 'window_manager.dart';\n\nclass SystemController extends ChangeNotifier {\n  final WindowManager windowManager;\n\n  SystemController({required this.windowManager});\n\n  void openApp(\n    String id,\n    String title,\n    Widget? content,\n    dynamic icon, {\n    String? url,\n  }) async {\n    if (url != null) {\n      final Uri uri = Uri.parse(url);\n      await launchUrl(uri, mode: LaunchMode.externalApplication);\n      return;\n    }\n    if (content != null) {\n      windowManager.openWindow(id, title, content, icon);\n    }\n  }\n}\n",
  "lib/models/config_model.dart": "import 'dart:convert';\n\nclass AppConfig {\n  final ProfileConfig profile;\n  final List<SkillCategory> skills;\n  final List<SocialLink> socials;\n  final List<CustomApp> apps;\n  final List<ExperienceItem> experience;\n  final List<EducationItem> education;\n  final List<String> certifications;\n\n  AppConfig({\n    required this.profile,\n    required this.skills,\n    required this.socials,\n    required this.apps,\n    required this.experience,\n    required this.education,\n    required this.certifications,\n  });\n\n  factory AppConfig.fromJson(Map<String, dynamic> json) {\n    return AppConfig(\n      profile: ProfileConfig.fromJson(json['profile'] ?? {}),\n      skills:\n          (json['skills'] as List?)?.map((e) {\n            if (e is String)\n              return SkillCategory(category: 'Other', items: [e]);\n            return SkillCategory.fromJson(e);\n          }).toList() ??\n          [],\n      socials:\n          (json['socials'] as List?)\n              ?.map((e) => SocialLink.fromJson(e))\n              .toList() ??\n          [],\n      apps:\n          (json['apps'] as List?)?.map((e) => CustomApp.fromJson(e)).toList() ??\n          [],\n      experience:\n          (json['experience'] as List?)\n              ?.map((e) => ExperienceItem.fromJson(e))\n              .toList() ??\n          [],\n      education:\n          (json['education'] as List?)\n              ?.map((e) => EducationItem.fromJson(e))\n              .toList() ??\n          [],\n      certifications: List<String>.from(json['certifications'] ?? []),\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'profile': profile.toJson(),\n    'skills': skills.map((e) => e.toJson()).toList(),\n    'socials': socials.map((e) => e.toJson()).toList(),\n    'apps': apps.map((e) => e.toJson()).toList(),\n    'experience': experience.map((e) => e.toJson()).toList(),\n    'education': education.map((e) => e.toJson()).toList(),\n    'certifications': certifications,\n  };\n}\n\nclass ProfileConfig {\n  final String name;\n  final String title;\n  final String about;\n  final String profilePic;\n  final String tabTitle;\n  final String terminalName;\n  final String systemName;\n  final String email;\n  final String location;\n\n  ProfileConfig({\n    required this.name,\n    required this.title,\n    required this.about,\n    required this.profilePic,\n    required this.tabTitle,\n    required this.terminalName,\n    required this.systemName,\n    required this.email,\n    required this.location,\n  });\n\n  factory ProfileConfig.fromJson(Map<String, dynamic> json) {\n    return ProfileConfig(\n      name: json['name'] ?? '',\n      title: json['title'] ?? '',\n      about: json['about'] ?? '',\n      profilePic: json['profilePic'] ?? 'assets/face.jpg',\n      tabTitle: json['tabTitle'] ?? 'Portfolio',\n      terminalName: json['terminalName'] ?? 'archie',\n      systemName: json['systemName'] ?? 'fyrWeb',\n      email: json['email'] ?? '',\n      location: json['location'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'name': name,\n    'title': title,\n    'about': about,\n    'profilePic': profilePic,\n    'tabTitle': tabTitle,\n    'terminalName': terminalName,\n    'systemName': systemName,\n    'email': email,\n    'location': location,\n  };\n}\n\nclass SocialLink {\n  final String id;\n  final String name;\n  final String url;\n  final String icon;\n\n  SocialLink({\n    required this.id,\n    required this.name,\n    required this.url,\n    required this.icon,\n  });\n\n  factory SocialLink.fromJson(Map<String, dynamic> json) {\n    return SocialLink(\n      id: json['id'] ?? '',\n      name: json['name'] ?? '',\n      url: json['url'] ?? '',\n      icon: json['icon'] ?? 'link',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'id': id,\n    'name': name,\n    'url': url,\n    'icon': icon,\n  };\n}\n\nclass CustomApp {\n  final String id;\n  final String title;\n  final String url;\n  final String icon;\n  final String color;\n\n  CustomApp({\n    required this.id,\n    required this.title,\n    required this.url,\n    required this.icon,\n    required this.color,\n  });\n\n  factory CustomApp.fromJson(Map<String, dynamic> json) {\n    return CustomApp(\n      id: json['id'] ?? '',\n      title: json['title'] ?? '',\n      url: json['url'] ?? '',\n      icon: json['icon'] ?? 'apps',\n      color: json['color'] ?? '0xFF2196F3',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'id': id,\n    'title': title,\n    'url': url,\n    'icon': icon,\n    'color': color,\n  };\n}\n\nclass ExperienceItem {\n  final String company;\n  final String role;\n  final String period;\n  final String description;\n\n  ExperienceItem({\n    required this.company,\n    required this.role,\n    required this.period,\n    required this.description,\n  });\n\n  factory ExperienceItem.fromJson(Map<String, dynamic> json) {\n    return ExperienceItem(\n      company: json['company'] ?? '',\n      role: json['role'] ?? '',\n      period: json['period'] ?? '',\n      description: json['description'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'company': company,\n    'role': role,\n    'period': period,\n    'description': description,\n  };\n}\n\nclass EducationItem {\n  final String school;\n  final String degree;\n  final String period;\n\n  EducationItem({\n    required this.school,\n    required this.degree,\n    required this.period,\n  });\n\n  factory EducationItem.fromJson(Map<String, dynamic> json) {\n    return EducationItem(\n      school: json['school'] ?? '',\n      degree: json['degree'] ?? '',\n      period: json['period'] ?? '',\n    );\n  }\n\n  Map<String, dynamic> toJson() => {\n    'school': school,\n    'degree': degree,\n    'period': period,\n  };\n}\n\nclass SkillCategory {\n  final String category;\n  final List<String> items;\n\n  SkillCategory({required this.category, required this.items});\n\n  factory SkillCategory.fromJson(Map<String, dynamic> json) {\n    return SkillCategory(\n      category: json['category'] ?? '',\n      items: List<String>.from(json['items'] ?? []),\n    );\n  }\n\n  Map<String, dynamic> toJson() => {'category': category, 'items': items};\n}\n",
};
